  (1, 'quiet_builder', 1, 'Bir dakikanı seç', 'Bugün yapacağın şeyi seç ve bir dakikayı geçmediğinden emin ol. Büyük seçilen her şey ikinci gün pazarlık konusu oluyor.', 'true', 'false'),
  (1, 'quiet_builder', 2, 'Kimsenin görmediği saate koy', 'Çıpanı zaten yalnız olduğun bir ana koy. Sen görülmek için değil, biriktirmek için yapıyorsun — düzenin de öyle olsun.', 'true', 'false'),
  (1, 'quiet_builder', 3, 'Bugün bir kez yap', 'Seçtiğin şeyi bugün bir kez yap. Bugünlük ölçü bu kadar.', 'true', 'false'),
  (2, 'quiet_builder', 1, 'Aynısını tekrarla', 'Dün ne yaptıysan bugün aynısını yap. Daha fazlasını değil — ikinci gün heyecan bitiyor ve geriye kalan şey iş oluyor.', 'true', 'false'),
  (2, 'quiet_builder', 2, 'Süreye değil, sağlamlığa bak', 'Ne kadar sürdüğü seni zaten ilgilendirmiyor. Bugün de ilgilendirmesin: oldu mu, o kadar.', 'true', 'false'),
  (2, 'quiet_builder', 3, 'Tek cümle yaz', 'Nasıl geçtiğini bir cümleyle kendine yaz. Yazılmayan şey olmamış sayılıyor.', 'true', 'false'),
  (3, 'quiet_builder', 1, 'Saati sabitle', 'Dünkü saati bugün de kullan. Hatırlamak zorunda kaldığın şey unutulur; aynı saate bağlanan şey hatırlanmaz, sadece olur.', 'true', 'false'),
  (3, 'quiet_builder', 2, 'Telefonu değil, bildirimi kaldır', 'Seni bölen şey ekran değil, bir şeyi kaçırdığın hissi. Bugün o hissi kapat.', 'true', 'false'),
