  (5, 'quiet_builder', 1, 'Kaçırdıysan geri dön', 'Bir gün boşluktur, iki gün karardır. Kaçırdıysan bugün devam et, telafi etmeye çalışma.', 'true', 'false'),
  (5, 'quiet_builder', 2, 'Zincire bak ve birine göster', 'Beş gündür duran şeyi bir kişiye göster. Görünmemek senin tercihin; hakkının teslim edilmemesi değil.', 'true', 'false'),
