  (6, 'quiet_builder', 2, 'Engelini söyleyerek kaldır', 'Seni geciktiren şeyi bugün tek başına çözme. Sessizce ilerlemek, sessizce tıkanmayı da kolaylaştırıyor.', 'true', 'false'),
